-- Plume Lite — initial schema (SQLite).
--
-- Every id is a Snowflake generated by the application (64-bit, time-ordered):
-- `ORDER BY id` is chronological and the creation time is encoded in the id itself.
-- Times are Unix timestamps in seconds. STRICT tables reject a value of the wrong
-- type instead of storing it silently.

CREATE TABLE users (
    id            INTEGER PRIMARY KEY,
    -- NOCASE: "Alice" and "alice" are the same account (usernames are ASCII only).
    username      TEXT    NOT NULL UNIQUE COLLATE NOCASE CHECK (length(username) BETWEEN 2 AND 32),
    password_hash TEXT    NOT NULL,                -- Argon2id PHC string
    created_at    INTEGER NOT NULL DEFAULT (unixepoch())
) STRICT;

-- Opaque bearer tokens. Only SHA-256(token) is stored, so a database leak does
-- not leak usable credentials. Revocation = DELETE (instant, unlike JWTs).
CREATE TABLE sessions (
    token_hash BLOB    PRIMARY KEY,
    user_id    INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at INTEGER NOT NULL DEFAULT (unixepoch()),
    expires_at INTEGER NOT NULL
) STRICT;
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

CREATE TABLE guilds (
    id         INTEGER PRIMARY KEY,
    name       TEXT    NOT NULL CHECK (length(name) BETWEEN 2 AND 100),
    owner_id   INTEGER NOT NULL REFERENCES users (id),  -- no cascade: transfer or delete the guild first
    created_at INTEGER NOT NULL DEFAULT (unixepoch())
) STRICT;
CREATE INDEX guilds_owner_id_idx ON guilds (owner_id);

CREATE TABLE guild_members (
    guild_id  INTEGER NOT NULL REFERENCES guilds (id) ON DELETE CASCADE,
    user_id   INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    joined_at INTEGER NOT NULL DEFAULT (unixepoch()),
    PRIMARY KEY (guild_id, user_id)            -- also serves "members of a guild" (sorted by user id)
) STRICT;
CREATE INDEX guild_members_user_id_idx ON guild_members (user_id);  -- "guilds of a user" (READY)

CREATE TABLE channels (
    id       INTEGER PRIMARY KEY,
    guild_id INTEGER NOT NULL REFERENCES guilds (id) ON DELETE CASCADE,
    name     TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    kind     INTEGER NOT NULL DEFAULT 0,       -- 0 = text (voice… later)
    position INTEGER NOT NULL DEFAULT 0
) STRICT;
CREATE INDEX channels_guild_id_idx ON channels (guild_id, position);

CREATE TABLE messages (
    id         INTEGER PRIMARY KEY,            -- creation time is encoded in the snowflake
    channel_id INTEGER NOT NULL REFERENCES channels (id) ON DELETE CASCADE,
    author_id  INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    content    TEXT    NOT NULL CHECK (length(content) BETWEEN 1 AND 2000),
    edited_at  INTEGER
) STRICT;
-- The hot path: "the N messages of a channel before/after X" is a single index range scan.
CREATE INDEX messages_channel_id_id_idx ON messages (channel_id, id DESC);
CREATE INDEX messages_author_id_idx ON messages (author_id);  -- ON DELETE CASCADE from users

CREATE TABLE invites (
    code       TEXT    PRIMARY KEY,
    guild_id   INTEGER NOT NULL REFERENCES guilds (id) ON DELETE CASCADE,
    inviter_id INTEGER NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    uses       INTEGER NOT NULL DEFAULT 0,
    max_uses   INTEGER CHECK (max_uses > 0),   -- NULL = unlimited
    expires_at INTEGER,                        -- NULL = never
    created_at INTEGER NOT NULL DEFAULT (unixepoch())
) STRICT;
CREATE INDEX invites_guild_id_idx ON invites (guild_id);
CREATE INDEX invites_inviter_id_idx ON invites (inviter_id);  -- ON DELETE CASCADE from users
